class Solution {
    public int countSubranges(int[] nums1, int[] nums2) {
        final int MOD = 1_000_000_007, OFF = 10000, SZ = 2 * OFF + 1;
        int[] dp = new int[SZ];
        long ans = 0;
        for (int i = 0; i < nums1.length; i++) {
            int a = nums1[i], b = nums2[i];
            int[] nd = new int[SZ];
            for (int d = 0; d < SZ; d++) {
                if (dp[d] == 0) continue;
                if (d + a < SZ) nd[d + a] = (nd[d + a] + dp[d]) % MOD;
                if (d - b >= 0) nd[d - b] = (nd[d - b] + dp[d]) % MOD;
            }
            nd[OFF + a] = (nd[OFF + a] + 1) % MOD;
            nd[OFF - b] = (nd[OFF - b] + 1) % MOD;
            dp = nd;
            ans = (ans + dp[OFF]) % MOD;
        }
        return (int) ans;
    }
}
